def _seed(mlp: MLP) -> int:
    """Domain-separate this estimator from every earlier sampling lane."""

    return (int(mlp.seed) ^ _SEED_LANE) & ((1 << 63) - 1)


def _reverse_bits_u32(value):
    """Vectorized 32-bit reversal for nested base-two lattice prefixes."""

    value = fnp.bitwise_or(
        fnp.bitwise_and(fnp.right_shift(value, 1), fnp.uint32(0x55555555)),
        fnp.left_shift(fnp.bitwise_and(value, fnp.uint32(0x55555555)), 1),
    )
    value = fnp.bitwise_or(
        fnp.bitwise_and(fnp.right_shift(value, 2), fnp.uint32(0x33333333)),
        fnp.left_shift(fnp.bitwise_and(value, fnp.uint32(0x33333333)), 2),
    )
    value = fnp.bitwise_or(
        fnp.bitwise_and(fnp.right_shift(value, 4), fnp.uint32(0x0F0F0F0F)),
        fnp.left_shift(fnp.bitwise_and(value, fnp.uint32(0x0F0F0F0F)), 4),
    )
    value = fnp.bitwise_or(
        fnp.bitwise_and(fnp.right_shift(value, 8), fnp.uint32(0x00FF00FF)),
        fnp.left_shift(fnp.bitwise_and(value, fnp.uint32(0x00FF00FF)), 8),
    )
    return fnp.bitwise_or(
        fnp.right_shift(value, 16),
        fnp.left_shift(value, 16),
    )


def _odd_lattice_multipliers(width: int):
    """Fixed source-only odd multipliers with a 32-bit avalanche map."""

    value = fnp.arange(width, dtype=fnp.uint32) + fnp.uint32(0x9E3779B9)
    value = fnp.bitwise_xor(value, fnp.right_shift(value, 16))
    value = value * fnp.uint32(0x7FEB352D)
    value = fnp.bitwise_xor(value, fnp.right_shift(value, 15))
    value = value * fnp.uint32(0x846CA68B)
    value = fnp.bitwise_xor(value, fnp.right_shift(value, 16))
    return fnp.bitwise_or(value, fnp.uint32(1))


def _walsh_directions(width: int, rank: int):
    """First ``rank`` normalized columns of a Sylvester-Hadamard matrix."""

    rows = fnp.arange(width, dtype=fnp.uint32)[:, None]
    columns = fnp.arange(rank, dtype=fnp.uint32)[None, :]
    value = fnp.bitwise_and(rows, columns)
    value = fnp.bitwise_xor(value, fnp.right_shift(value, 16))
    value = fnp.bitwise_xor(value, fnp.right_shift(value, 8))
    value = fnp.bitwise_xor(value, fnp.right_shift(value, 4))
    value = fnp.bitwise_xor(value, fnp.right_shift(value, 2))
    parity = fnp.bitwise_and(
        fnp.bitwise_xor(value, fnp.right_shift(value, 1)),
        fnp.uint32(1),
    )
    signs = 1.0 - 2.0 * fnp.asarray(parity, dtype=fnp.float64)
    return signs / math.sqrt(float(width))


def _shifted_lattice_normals(count: int, width: int, rng):
    """One independently shifted rank-1 lattice block, mapped to normals."""

    indices = fnp.arange(count, dtype=fnp.uint32)
    reversed_indices = _reverse_bits_u32(indices)
    multipliers = _odd_lattice_multipliers(width)
    residues = reversed_indices[:, None] * multipliers[None, :]
    unit = fnp.asarray(residues, dtype=fnp.float64) * _UINT32_SCALE
    shift = rng.uniform(0.0, 1.0, size=(1, width))
    unit = fnp.remainder(unit + shift, 1.0)
    unit = fnp.maximum(fnp.minimum(unit, 1.0 - _PPF_EPS), _PPF_EPS)
    return fnp.asarray(flops.stats.norm.ppf(unit), dtype=fnp.float32)


def _sobol_direction_numbers(width: int):
    """Load the exact frozen Joe--Kuo 1024x32 little-endian uint32 table."""

    if width != 1_024:
        raise ValueError("frozen Sobol table requires width 1024")
    directions = fnp.frombuffer(
        bytes.fromhex(_SOBOL_DIRECTION_HEX),
        dtype=fnp.uint32,
    )
    return fnp.reshape(directions, (width, _SOBOL_BITS))


def _sobol_direction_bits(directions):
    bit_positions = fnp.subtract(
        fnp.uint32(_SOBOL_BITS - 1),
        fnp.arange(_SOBOL_BITS, dtype=fnp.uint32),
    )
    return fnp.bitwise_and(
        fnp.right_shift(
            directions[:, :, None],
            bit_positions[None, None, :],
        ),
        fnp.uint32(1),
    )


def _scrambled_sobol_normals(count: int, width: int, rng, direction_bits):
    """One SciPy-compatible LMS+digital-shift scrambled Sobol replicate."""

    power = count.bit_length() - 1
    if count != 1 << power:
        raise ValueError("each Sobol replicate must contain a power of two points")

    shift_bits = rng.integers(
        0,
        2,
        size=(width, _SOBOL_BITS),
        dtype=fnp.uint32,
    )
    low_to_high = fnp.arange(_SOBOL_BITS, dtype=fnp.uint32)
    shift = fnp.sum(
        fnp.left_shift(shift_bits, low_to_high[None, :]),
        axis=1,
        dtype=fnp.uint32,
    )

    random_ltm = rng.integers(
        0,
        2,
        size=(width, _SOBOL_BITS, _SOBOL_BITS),
        dtype=fnp.uint32,
    )
    ltm = fnp.tril(random_ltm, k=-1)
    diagonal_index = fnp.arange(_SOBOL_BITS, dtype=fnp.uint32)
    diagonal_mask = diagonal_index[:, None] == diagonal_index[None, :]
    ltm = fnp.where(diagonal_mask[None, :, :], fnp.uint32(1), ltm)
    # Matrix multiplication over GF(2).  Array bit index zero is the MSB,
    # exactly matching scipy.stats._sobol._cscramble.
    scrambled_bits = fnp.bitwise_and(
        fnp.einsum(
            "dri,dki->dkr",
            ltm,
            direction_bits[:, :power, :],
        ),
        fnp.uint32(1),
    )
    high_to_low = fnp.subtract(fnp.uint32(_SOBOL_BITS - 1), low_to_high)
    scrambled_directions = fnp.sum(
        fnp.left_shift(
            scrambled_bits,
            high_to_low[None, None, :],
        ),
        axis=2,
        dtype=fnp.uint32,
    )

    indices = fnp.arange(count, dtype=fnp.uint32)
    gray = fnp.bitwise_xor(indices, fnp.right_shift(indices, fnp.uint32(1)))
    residues = fnp.zeros((count, width), dtype=fnp.uint32) + shift[None, :]
    for bit in range(power):
        selected = fnp.bitwise_and(
            fnp.right_shift(gray, fnp.uint32(bit)),
            fnp.uint32(1),
        )
        residues = fnp.where(
            selected[:, None] != 0,
            fnp.bitwise_xor(
                residues,
                scrambled_directions[:, bit][None, :],
            ),
            residues,
        )

    unit = fnp.asarray(residues, dtype=fnp.float64) * _UINT32_SCALE
    unit = fnp.maximum(fnp.minimum(unit, 1.0 - _PPF_EPS), _PPF_EPS)
    return fnp.asarray(flops.stats.norm.ppf(unit), dtype=fnp.float32)


def _sobol_bank(blocks, width: int, rng):
    directions = _sobol_direction_numbers(width)
    direction_bits = _sobol_direction_bits(directions)
    return fnp.concatenate(
        [
            _scrambled_sobol_normals(count, width, rng, direction_bits)
            for count in blocks
        ],
        axis=0,
    )


def _angular_whitening_state(samples):
    """Angularize, center, and return the folded first-layer whitening map."""

    count = int(samples.shape[0])
    width = int(samples.shape[1])
    radii = fnp.sqrt(fnp.sum(samples * samples, axis=1))
    angular = samples / radii[:, None]
    location = fnp.asarray(
        fnp.mean(angular, axis=0, dtype=fnp.float64),
        dtype=fnp.float32,
    )
    centered = angular - location[None, :]
    # Same-object self-contraction intentionally invokes flopscope's symmetric
    # Gram path.  Multiplication by width makes E[S]=I for sphere directions.
    covariance = (float(width) / float(count)) * fnp.einsum(
        "ni,nj->ij",
        centered,
        centered,
    )
    covariance = 0.5 * (covariance + fnp.transpose(covariance))
    covariance = covariance + _WHITEN_RIDGE * fnp.eye(
        width,
        dtype=fnp.float32,
    )
    lower = fnp.linalg.cholesky(covariance)
    return centered, fnp.transpose(lower)


def _iid_paired_whitening_state(positive):
    """Exact-covariance Stiefel spelling for n IID rows and their negatives."""

    base_count = int(positive.shape[0])
    covariance = fnp.einsum(
        "ni,nj->ij",
        positive,
        positive,
    ) / float(base_count)
    covariance = 0.5 * (covariance + fnp.transpose(covariance))
    lower = fnp.linalg.cholesky(covariance)
    paired = fnp.concatenate((positive, -positive), axis=0)
    return paired, fnp.transpose(lower)


def _forward_means(samples, weights, *, first_upper=None, output_scale=1.0):
    """Propagate one bank; optionally fold X L^-T into W1 as solve(L.T,W1)."""

    state = samples
    rows = []
    for layer0, weights_raw in enumerate(weights):
        layer_weights = fnp.asarray(weights_raw, dtype=fnp.float32)
        if layer0 == 0 and first_upper is not None:
            layer_weights = fnp.linalg.solve(first_upper, layer_weights)
        state = fnp.maximum(state @ layer_weights, 0.0)
        rows.append(
            output_scale * fnp.mean(state, axis=0, dtype=fnp.float64)
        )
    return fnp.asarray(fnp.stack(rows, axis=0), dtype=fnp.float32)


def _hermite_coefficients(alpha, pdf, cdf):
    """Probabilists-Hermite coefficients of ReLU(mu + sigma Z)."""

    coefficients = [pdf + alpha * cdf, cdf, pdf / math.sqrt(2.0)]
    he_previous = fnp.ones_like(alpha)
    he_current = -alpha
    factorial = 2.0
    for order in range(3, _HERMITE_ORDER + 1):
        factorial *= order
        coefficients.append(he_current * pdf / math.sqrt(factorial))
        he_previous, he_current = (
            he_current,
            (-alpha) * he_current - (order - 2) * he_previous,
        )
    return coefficients


def _gaussian_relu_mean(location, response):
    """Exact ideal-law mean of relu(location + Z @ response)."""

    variance = fnp.sum(response * response, axis=0)
    positive = variance > 0.0
    safe_variance = fnp.where(positive, variance, 1.0)
    sigma = fnp.sqrt(safe_variance)
    alpha = location / sigma
    pdf = fnp.exp(-0.5 * alpha * alpha) / _SQRT_2PI
    cdf = flops.stats.norm.cdf(alpha)
    gaussian = sigma * pdf + location * cdf
    return fnp.where(positive, gaussian, fnp.maximum(location, 0.0))


def _block_bounds(blocks):
    start = 0
    bounds = []
    for count in blocks:
        stop = start + count
        bounds.append((start, stop, count))
        start = stop
    return tuple(bounds)


def _fixed_beta_row(actual, proxy, proxy_mean, blocks):
    """beta=1 control estimate, block aggregation written explicitly."""

    total = float(sum(blocks))
    aggregate = fnp.zeros(int(actual.shape[1]), dtype=fnp.float64)
    for start, stop, count in _block_bounds(blocks):
        residual = fnp.asarray(actual[start:stop], dtype=fnp.float64) - proxy[start:stop]
        aggregate = aggregate + float(count) * fnp.mean(
            residual,
            axis=0,
            dtype=fnp.float64,
        )
    return proxy_mean + aggregate / total


def _crossfit_beta_row(actual, proxy, proxy_mean, blocks):
    """Leave-one-shift-out beta, fitted separately for every output neuron."""

    block_stats = []
    for start, stop, count in _block_bounds(blocks):
        f_block = fnp.asarray(actual[start:stop], dtype=fnp.float64)
        c_block = proxy[start:stop] - proxy_mean[None, :]
        block_stats.append(
            (
                float(count),
                fnp.sum(f_block, axis=0, dtype=fnp.float64),
                fnp.sum(c_block, axis=0, dtype=fnp.float64),
                fnp.sum(f_block * c_block, axis=0, dtype=fnp.float64),
                fnp.sum(c_block * c_block, axis=0, dtype=fnp.float64),
            )
        )

    total_count = sum(item[0] for item in block_stats)
    all_f = sum((item[1] for item in block_stats), fnp.zeros_like(block_stats[0][1]))
    all_c = sum((item[2] for item in block_stats), fnp.zeros_like(block_stats[0][2]))
    all_fc = sum((item[3] for item in block_stats), fnp.zeros_like(block_stats[0][3]))
    all_c2 = sum((item[4] for item in block_stats), fnp.zeros_like(block_stats[0][4]))

    weighted = fnp.zeros_like(all_f)
    for count, f_sum, c_sum, fc_sum, c2_sum in block_stats:
        train_count = total_count - count
        train_f = all_f - f_sum
        train_c = all_c - c_sum
        train_fc = all_fc - fc_sum
        train_c2 = all_c2 - c2_sum
        covariance_numerator = train_fc - train_f * train_c / train_count
        variance_numerator = fnp.maximum(
            train_c2 - train_c * train_c / train_count,
            0.0,
        )
        beta = covariance_numerator / (
            variance_numerator + _BETA_RIDGE * train_count
        )
        beta = fnp.maximum(fnp.minimum(beta, _BETA_CLIP), -_BETA_CLIP)
        held_mean = f_sum / count - beta * (c_sum / count)
        weighted = weighted + count * held_mean
    return weighted / total_count


class _ResponseEstimator(BaseEstimator):
    """Common final-only response implementation; subclasses freeze choices."""

    CROSS_FIT = False
    RESPONSE_RANK = 1_024
    RQMC_BLOCKS = _RQMC_BLOCKS_R1024

    def predict(self, mlp: MLP, budget: int) -> fnp.ndarray:
        del budget
        width = int(mlp.width)
        rank = int(self.RESPONSE_RANK)
        if width != 1_024 or rank not in (256, 1_024):
            raise ValueError("frozen response candidates require width 1024 and rank 256/1024")

        rng = fnp.random.default_rng(_seed(mlp))
        blocks = [
            _shifted_lattice_normals(count, width, rng)
            for count in self.RQMC_BLOCKS
        ]
        actual = fnp.concatenate(blocks, axis=0)
        if rank == width:
            directions = None
            latent = fnp.asarray(actual, dtype=fnp.float64)
        else:
            directions = _walsh_directions(width, rank)
            latent = fnp.asarray(actual, dtype=fnp.float64) @ directions

        mean = fnp.zeros(width, dtype=fnp.float64)
        covariance = fnp.eye(width, dtype=fnp.float64)
        response = None
        rows = []

        for layer0, weights_raw in enumerate(mlp.weights):
            weights32 = fnp.asarray(weights_raw, dtype=fnp.float32)
            weights64 = fnp.asarray(weights_raw, dtype=fnp.float64)

            pre_mean = fnp.transpose(weights64) @ mean
            pre_covariance = fnp.einsum(
                "ij,ia,jb->ab",
                covariance,
                weights64,
                weights64,
            )
            pre_variance = fnp.maximum(fnp.diag(pre_covariance), _VAR_FLOOR)
            pre_sigma = fnp.sqrt(pre_variance)
            alpha = pre_mean / pre_sigma
            pdf = fnp.exp(-0.5 * alpha * alpha) / _SQRT_2PI
            cdf = flops.stats.norm.cdf(alpha)
            coefficients = _hermite_coefficients(alpha, pdf, cdf)
            gaussian_mean = pre_sigma * coefficients[0]

            # With the identity basis, the effective original-coordinate
            # response is W1 at layer one and R_{l-1} W_l thereafter.
            if response is None:
                response_pre = (
                    weights64
                    if directions is None
                    else fnp.transpose(directions) @ weights64
                )
            else:
                response_pre = response @ weights64

            pre_actual = actual @ weights32
            next_actual = fnp.maximum(pre_actual, 0.0)
            if layer0 == 0:
                # z1 is exactly Gaussian in the ideal law and q1=f1, hence the
                # first-layer controlled estimate is analytic with zero residual.
                proxy_post = fnp.asarray(next_actual, dtype=fnp.float64)
                proxy_mean = gaussian_mean
                row = proxy_mean
            elif layer0 + 1 < int(mlp.depth):
                # The official raw objective is L16.  Do not spend a pathwise
                # proxy multiply on unscored intermediate layers.
                proxy_post = None
                proxy_mean = None
                row = gaussian_mean
            else:
                proxy_pre = pre_mean[None, :] + latent @ response_pre
                proxy_post = fnp.maximum(proxy_pre, 0.0)
                proxy_mean = _gaussian_relu_mean(pre_mean, response_pre)
                if self.CROSS_FIT:
                    row = _crossfit_beta_row(
                        next_actual,
                        proxy_post,
                        proxy_mean,
                        self.RQMC_BLOCKS,
                    )
                else:
                    row = _fixed_beta_row(
                        next_actual,
                        proxy_post,
                        proxy_mean,
                        self.RQMC_BLOCKS,
                    )
            rows.append(row)

            correlation = pre_covariance / fnp.outer(pre_sigma, pre_sigma)
            covariance = fnp.zeros((width, width), dtype=fnp.float64)
            correlation_power = correlation
            for order in range(1, _HERMITE_ORDER + 1):
                coefficient = coefficients[order]
                covariance = covariance + fnp.outer(
                    coefficient,
                    coefficient,
                ) * correlation_power
                correlation_power = correlation_power * correlation
            covariance = covariance * fnp.outer(pre_sigma, pre_sigma)
            exact_variance = fnp.maximum(
                pre_variance
                * ((1.0 + alpha * alpha) * cdf + alpha * pdf)
                - gaussian_mean * gaussian_mean,
                _VAR_FLOOR,
            )
            diagonal_tail = fnp.maximum(
                exact_variance - fnp.diag(covariance),
                0.0,
            )
            covariance = covariance + fnp.diag(diagonal_tail)
            mean = gaussian_mean
            response = response_pre * cdf[None, :]
            actual = next_actual

        return fnp.asarray(fnp.stack(rows, axis=0), dtype=fnp.float32)


class EstimatorRank1024Fixed(_ResponseEstimator):
    """Full-rank control with the preregistered fixed coefficient beta=1."""

    CROSS_FIT = False
    RESPONSE_RANK = 1_024
    RQMC_BLOCKS = _RQMC_BLOCKS_R1024


class EstimatorRank1024Crossfit(_ResponseEstimator):
    """Full-rank control with leave-one-random-shift-out fitted coefficients."""

    CROSS_FIT = True
    RESPONSE_RANK = 1_024
    RQMC_BLOCKS = _RQMC_BLOCKS_R1024


class EstimatorRank256Fixed(_ResponseEstimator):
    """Rank-256 Walsh control with the fixed coefficient beta=1."""

    CROSS_FIT = False
    RESPONSE_RANK = 256
    RQMC_BLOCKS = _RQMC_BLOCKS_R256


class EstimatorRank256Crossfit(_ResponseEstimator):
    """Rank-256 Walsh control with leave-one-shift-out coefficients."""

    CROSS_FIT = True
    RESPONSE_RANK = 256
    RQMC_BLOCKS = _RQMC_BLOCKS_R256


class EstimatorRawRQMC(BaseEstimator):
    """beta=0 comparator: maximal target-free RQMC without response FLOPs."""

    def predict(self, mlp: MLP, budget: int) -> fnp.ndarray:
        del budget
        width = int(mlp.width)
        if width != 1_024:
            raise ValueError("frozen raw-RQMC candidate requires width 1024")
        rng = fnp.random.default_rng(_seed(mlp))
        actual = fnp.concatenate(
            [
                _shifted_lattice_normals(count, width, rng)
                for count in _RQMC_BLOCKS_RAW
            ],
            axis=0,
        )
        rows = []
        for weights_raw in mlp.weights:
            weights32 = fnp.asarray(weights_raw, dtype=fnp.float32)
            actual = fnp.maximum(actual @ weights32, 0.0)
            rows.append(fnp.mean(actual, axis=0, dtype=fnp.float64))
        return fnp.asarray(fnp.stack(rows, axis=0), dtype=fnp.float32)


class EstimatorScrambledSobolRaw(BaseEstimator):
    """Primary unbiased-ideal-law beta=0 LMS+shift Sobol comparator."""

    def predict(self, mlp: MLP, budget: int) -> fnp.ndarray:
        del budget
        width = int(mlp.width)
        if width != 1_024:
            raise ValueError("frozen Sobol candidate requires width 1024")
        rng = fnp.random.default_rng(_seed(mlp) ^ 0x10A7F4C93E8265BD)
        samples = _sobol_bank(_SOBOL_RAW_BLOCKS, width, rng)
        return _forward_means(samples, mlp.weights)


class EstimatorScrambledSobolAngularWhitened(BaseEstimator):
    """LMS+shift Sobol, exact angular split, then finite-bank whitening."""

    def predict(self, mlp: MLP, budget: int) -> fnp.ndarray:
        del budget
        width = int(mlp.width)
        if width != 1_024:
            raise ValueError("frozen Sobol candidate requires width 1024")
        rng = fnp.random.default_rng(_seed(mlp) ^ 0x74B18D20CF9536EA)
        samples = _sobol_bank(_SOBOL_WHITEN_BLOCKS, width, rng)
        angular, upper = _angular_whitening_state(samples)
        return _forward_means(
            angular,
            mlp.weights,
            first_upper=upper,
            output_scale=_CHI_MEAN_1024,
        )


class EstimatorIIDAngularWhitenedAntithetic(BaseEstimator):
    """IID angular antithetic pairs plus one finite-bank whitening transform."""

    def predict(self, mlp: MLP, budget: int) -> fnp.ndarray:
        del budget
        width = int(mlp.width)
        if width != 1_024:
            raise ValueError("frozen IID candidate requires width 1024")
        rng = fnp.random.default_rng(_seed(mlp) ^ 0x4F63A1DE90827BC5)
        positive = rng.standard_normal(
            (_IID_WHITEN_SAMPLES // 2, width),
            dtype=fnp.float32,
        )
        paired, upper = _iid_paired_whitening_state(positive)
        return _forward_means(
            paired,
            mlp.weights,
            first_upper=upper,
            output_scale=_IID_PAIRED_RADIAL_CORRECTION,
        )


class EstimatorIIDAngularWhitened(EstimatorIIDAngularWhitenedAntithetic):
    """Compatibility alias; the frozen IID whitening lane is explicitly paired."""


class Estimator(EstimatorScrambledSobolRaw):
    """Interface default; promotion remains separate root authority."""
